13	#[derive(Debug, Clone)]
14	pub struct QuickFix {
15	    pub title: String,
16	    pub edits: Vec<Edit>,
17	    pub preferred: bool,
18	}
19	
20	pub fn code_actions(
21	    db: &dyn Db,
22	    file: File,
23	    diagnostic_range: TextRange,
24	    diagnostic_id: &str,
25	) -> Vec<QuickFix> {
26	    let registry = db.lint_registry();
27	    let Ok(lint_id) = registry.get(diagnostic_id) else {
28	        return Vec::new();
29	    };
30	
31	    let mut actions = Vec::new();
32	
33	    // Suggest imports/qualifications for unresolved references (often ideal)
34	    let is_unresolved_reference =
35	        lint_id == LintId::of(&UNRESOLVED_REFERENCE) || lint_id == LintId::of(&UNDEFINED_REVEAL);
36	    if is_unresolved_reference
37	        && let Some(import_quick_fix) = unresolved_fixes(db, file, diagnostic_range)
38	    {
39	        actions.extend(import_quick_fix);
40	    }
41	
42	    // Suggest just suppressing the lint (always a valid option, but never ideal)
43	    actions.push(QuickFix {
44	        title: format!("Ignore '{}' for this line", lint_id.name()),
45	        edits: suppress_single(db, file, lint_id, diagnostic_range).into_edits(),
46	        preferred: false,
47	    });
48	
49	    actions
50	}
51	
52	fn unresolved_fixes(
53	    db: &dyn Db,
54	    file: File,
55	    diagnostic_range: TextRange,
56	) -> Option<impl Iterator<Item = QuickFix>> {
57	    let parsed = parsed_module(db, file).load(db);
58	    let node = covering_node(parsed.syntax().into(), diagnostic_range).node();
59	    let symbol = &node.expr_name()?.id;
60	
61	    Some(
62	        completion::unresolved_fixes(db, file, &parsed, symbol, node)
63	            .into_iter()
64	            .map(|import| QuickFix {
65	                title: import.label,
66	                edits: vec![import.edit],
67	                preferred: true,
68	            }),
69	    )
70	}
