use crate::server::Result;
use crate::server::api::RequestHandler;
use crate::server::api::traits::SyncRequestHandler;
use crate::session::Session;
use crate::session::client::Client;

pub(crate) struct CodeActionResolveRequestHandler;

impl RequestHandler for CodeActionResolveRequestHandler {
    type RequestType = CodeActionResolveRequest;
}

impl SyncRequestHandler for CodeActionResolveRequestHandler {
    fn run(
        session: &mut Session,
        _client: &Client,
        code_action: CodeAction,
    ) -> Result<CodeAction> {
        // The `data` field carries the URL of the document that the code action applies to.
        // If there's no data, there's nothing to resolve, so return the action unchanged.
        let Some(data) = code_action.data.clone() else {
            return Ok(code_action);
        };

        // If the data can't be parsed as a document URL, we can't resolve the action, so return
        // it unchanged rather than failing the request.
        let Ok(url) = serde_json::from_value::<Url>(data) else {
            return Ok(code_action);
        };

        // If the document isn't open in the session there's nothing to resolve against, so return
        // the action unchanged.
        if session.snapshot_document(&url).is_err() {
            return Ok(code_action);
        }

        // All code actions are currently computed eagerly with their edits already attached, so
        // there is nothing further to resolve.
        Ok(code_action)
    }
}
